import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"溫公易說 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"溫公易說 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"classics/wengong/053.md","filePath":"classics/wengong/053.md"}'),l={name:"classics/wengong/053.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><h3 id="彖曰-艮-止也。時止則止-時行則行。動靜不失其時-其道光明。艮其止-止其所也。上下敵應-不相與也-是以不獲其身-行其庭-不見其人-無咎也。" tabindex="-1">彖曰：艮，止也。時止則止，時行則行。動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也，是以不獲其身，行其庭，不見其人，無咎也。 <a class="header-anchor" href="#彖曰-艮-止也。時止則止-時行則行。動靜不失其時-其道光明。艮其止-止其所也。上下敵應-不相與也-是以不獲其身-行其庭-不見其人-無咎也。" aria-label="Permalink to “彖曰：艮，止也。時止則止，時行則行。動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也，是以不獲其身，行其庭，不見其人，無咎也。”">​</a></h3><h3 id="象曰-兼山-艮。君子以思不出其位。" tabindex="-1">象曰：兼山，艮。君子以思不出其位。 <a class="header-anchor" href="#象曰-兼山-艮。君子以思不出其位。" aria-label="Permalink to “象曰：兼山，艮。君子以思不出其位。”">​</a></h3><h3 id="初六-艮其趾-無咎-利永貞-象曰-艮其趾-未失正也。" tabindex="-1">初六：艮其趾，無咎，利永貞 象曰：艮其趾，未失正也。 <a class="header-anchor" href="#初六-艮其趾-無咎-利永貞-象曰-艮其趾-未失正也。" aria-label="Permalink to “初六：艮其趾，無咎，利永貞 象曰：艮其趾，未失正也。”">​</a></h3><p>其位則下，其事則初，止而不行，何咎之有？抑君子於其所止，不可不謹擇也。止於永貞，利莫大焉。</p><h3 id="六二-艮其腓-不拯其隨-其心不快-象曰-不拯其隨-未退聽也。" tabindex="-1">六二：艮其腓，不拯其隨，其心不快 象曰：不拯其隨，未退聽也。 <a class="header-anchor" href="#六二-艮其腓-不拯其隨-其心不快-象曰-不拯其隨-未退聽也。" aria-label="Permalink to “六二：艮其腓，不拯其隨，其心不快 象曰：不拯其隨，未退聽也。”">​</a></h3><h3 id="九三-艮其限-列其夤-厲燻心-象曰-艮其限-危燻心也。" tabindex="-1">九三：艮其限，列其夤，厲燻心 象曰：艮其限，危燻心也。 <a class="header-anchor" href="#九三-艮其限-列其夤-厲燻心-象曰-艮其限-危燻心也。" aria-label="Permalink to “九三：艮其限，列其夤，厲燻心 象曰：艮其限，危燻心也。”">​</a></h3><h3 id="六四-艮其身-無咎-象曰-艮其身-止諸躬也。" tabindex="-1">六四：艮其身，無咎 象曰：艮其身，止諸躬也。 <a class="header-anchor" href="#六四-艮其身-無咎-象曰-艮其身-止諸躬也。" aria-label="Permalink to “六四：艮其身，無咎 象曰：艮其身，止諸躬也。”">​</a></h3><h3 id="六五-艮其輔-言有序-悔亡-象曰-艮其輔-以中正也。" tabindex="-1">六五：艮其輔，言有序，悔亡 象曰：艮其輔，以中正也。 <a class="header-anchor" href="#六五-艮其輔-言有序-悔亡-象曰-艮其輔-以中正也。" aria-label="Permalink to “六五：艮其輔，言有序，悔亡 象曰：艮其輔，以中正也。”">​</a></h3><p>凡剛柔當位正之象也。孔子贊幹之九二龍德而正中，艮之六五曰以中正，何也？曰：艮六五文之誤也，當雲以正中也。正中者，正得其中，非既正又中也。然則二爻其為不正乎？曰：非謂其然也。中正者，道之貫也，相須而成，相輔而行者也。</p><h3 id="上九-敦艮-吉-象曰-敦艮之吉-以厚終也。" tabindex="-1">上九：敦艮，吉 象曰：敦艮之吉，以厚終也。 <a class="header-anchor" href="#上九-敦艮-吉-象曰-敦艮之吉-以厚終也。" aria-label="Permalink to “上九：敦艮，吉 象曰：敦艮之吉，以厚終也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
